(function(N){'use strict';const T=N.Combat274,C=T.config,copy=q=>JSON.parse(JSON.stringify(q)),paths=['reassess.light','reassess.medium','reassess.heavy','minimum.heavy','separation','speed'],get=(o,p)=>p.split('.').reduce((q,k)=>q[k],o),put=(o,p,v)=>{const a=p.split('.'),k=a.pop();a.reduce((q,k)=>q[k],o)[k]=v},freeze=o=>{for(const v of Object.values(o))if(v&&typeof v==='object')freeze(v);return Object.freeze(o)},baseline=freeze(copy(C)),history=[],redo=[];let pending=null;
function safe(g){return[g.player,...g.enemies].every(e=>!e.act&&!e.hold&&!e.heldBy&&!e.flight&&!e.grappleSession119?.active);}
function commit(g){if(!pending||!safe(g))return false;const q=pending;for(const p of paths)put(C,p,get(q.after,p));if(q.kind==='undo'){history.pop();redo.push(q.entry)}else if(q.kind==='redo'){redo.pop();history.push(q.entry)}else{history.push({before:q.before,after:q.after,at:g.time,timestamp:new Date().toISOString(),properties:paths.filter(p=>get(q.before,p)!==get(q.after,p)),build:274});redo.length=0;}pending=null;N.Audit135.record(g,'reactionSettings274',{operation:q.kind,modified:paths.filter(p=>get(C,p)!==get(baseline,p))});return true;}
function request(g,after,kind='set',entry){if(pending)throw Error('A change is queued until combat is safe.');pending={before:copy(C),after,kind,entry};commit(g);return !pending;}
function set(g,p,value){if(!paths.includes(p))throw Error('Unsupported property');const v=Number(value),min=p==='separation'?24:p==='speed'?8:0,max=p==='separation'?96:p==='speed'?90:p==='minimum.heavy'?45:30;if(!Number.isFinite(v)||v<min||v>max)throw Error('Allowed range '+min+'–'+max);const q=copy(C);put(q,p,v);return request(g,q);}
function reset(g,p){return set(g,p,get(baseline,p));}function undo(g){if(!history.length)return false;const e=history.at(-1);return request(g,copy(e.before),'undo',e);}function again(g){if(!redo.length)return false;const e=redo.at(-1);return request(g,copy(e.after),'redo',e);}function resetAll(g,confirmed=false){if(!confirmed)throw Error('Confirm reset of '+paths.filter(p=>get(C,p)!==get(baseline,p)).length+' modified values');return request(g,copy(baseline),'reset all');}
const tick=N.Brawler.prototype.tick;N.Brawler.prototype.tick=function(dt,i){const r=tick.call(this,dt,i);commit(this);return r;};T.settings={baseline,paths,get,set,reset,undo,redo:again,resetAll,safe,report:()=>({baseline:copy(baseline),current:copy(C),modified:paths.filter(p=>get(C,p)!==get(baseline,p)),pending:pending?.kind||null,history:copy(history),redo:redo.length})};
})(globalThis.NeonCombat);
